import { compileExpression, resolveName } from "@allurereport/core-api/expression";
export const resolvePluginExpression = (kind, value, path, context) => {
    if (typeof value !== "string") {
        return value;
    }
    const { env } = context;
    if (typeof kind === "function") {
        return kind(value, { ...context, path });
    }
    switch (kind) {
        case "name":
            return resolveName(value, path, context);
        case "testFilter": {
            const evaluate = compileExpression(value, path, { test: "map", env: "map" }, { resultType: "bool" });
            return (test) => evaluate({ test, env });
        }
        case "qualityGateFilter": {
            const evaluate = compileExpression(value, path, { result: "map", env: "map" }, { resultType: "bool" });
            return (result) => evaluate({ result, env });
        }
    }
};
